/* Storelib Payments on Airwallex, alongside Stripe and switched off until a creator is put on it. `payment_accounts` is a creator's Airwallex connected account as Airwallex last described it: the account id, individual or business, the lifecycle status exactly as Airwallex sent it (CREATED, SUBMITTED, ACTION_REQUIRED, ACTIVE, SUSPENDED, DORMANT, CLOSED, or a newer value kept as sent), the onboarding form's own status apart from it, what Airwallex is asking for (codes only, nothing personal), and a masked payout destination (bank name, country, currency, last four). `payment_webhook_events` is every Airwallex event id once, so a retried or repeated delivery changes nothing, with no payload kept. `payment_audit_log` is every change of payment or payout state and who caused it. `payment_fee_records` is each Airwallex payment: the total, Storelib's fee, the creator's share, and what was refunded or taken back. `payment_balances` is the creator's wallet balances as Airwallex last reported them, per currency. `payment_payouts` is each payout Storelib asked Airwallex for, under its own id so a retry cannot pay twice. `orders.provider_payment_id` is the Airwallex payment an order came from (`orders.provider` already says which provider), held unique. Every table is the server's alone: row level security on, no policy, and no grant to the public or signed in keys. Changes nothing for Stripe creators. Needs nothing else. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.payment_accounts (creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('airwallex')), provider_account_id text UNIQUE CHECK (provider_account_id IS NULL OR provider_account_id ~ '^acct_[A-Za-z0-9_-]+$'), account_kind text CHECK (account_kind IN ('individual', 'business')), country text CHECK (country IS NULL OR country ~ '^[A-Z]{2}$'), lifecycle_status text CHECK (lifecycle_status IS NULL OR length(lifecycle_status) <= 40), form_status text CHECK (form_status IS NULL OR form_status IN ('INIT', 'SUBMITTED', 'SUCCESS', 'FAILURE')), next_action_type text CHECK (next_action_type IS NULL OR length(next_action_type) <= 80), requirements jsonb, hosted_flow_id text, payout_beneficiary_id text, payout_destination jsonb, consent_at timestamptz, status_synced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (creator_id, provider));
CREATE TABLE IF NOT EXISTS public.payment_webhook_events (provider text NOT NULL, event_id text NOT NULL CHECK (length(event_id) BETWEEN 1 AND 200), name text NOT NULL CHECK (length(name) <= 120), account_id text, object_id text, event_created_at timestamptz, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, outcome text NOT NULL DEFAULT 'processing' CHECK (outcome IN ('processing', 'done', 'ignored', 'failed')), error text CHECK (error IS NULL OR length(error) <= 500), attempts integer NOT NULL DEFAULT 1, PRIMARY KEY (provider, event_id));
CREATE TABLE IF NOT EXISTS public.payment_audit_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL, provider text NOT NULL, kind text NOT NULL CHECK (length(kind) <= 60), from_state text CHECK (from_state IS NULL OR length(from_state) <= 60), to_state text CHECK (to_state IS NULL OR length(to_state) <= 60), ref text CHECK (ref IS NULL OR length(ref) <= 200), actor text NOT NULL CHECK (actor IN ('creator', 'webhook', 'system', 'admin')));
CREATE TABLE IF NOT EXISTS public.payment_fee_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, provider_payment_id text NOT NULL, checkout_id text NOT NULL, creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL, currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), gross_minor bigint NOT NULL CHECK (gross_minor >= 0), platform_fee_minor bigint NOT NULL CHECK (platform_fee_minor >= 0), creator_share_minor bigint NOT NULL CHECK (creator_share_minor >= 0), refunded_minor bigint NOT NULL DEFAULT 0 CHECK (refunded_minor >= 0), clawed_back_minor bigint NOT NULL DEFAULT 0 CHECK (clawed_back_minor >= 0), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'succeeded', 'failed', 'cancelled', 'refunded', 'partially_refunded', 'disputed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT payment_fee_records_split CHECK (platform_fee_minor + creator_share_minor = gross_minor), UNIQUE (provider, provider_payment_id));
CREATE TABLE IF NOT EXISTS public.payment_balances (creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL, currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), available_minor bigint NOT NULL DEFAULT 0, pending_minor bigint NOT NULL DEFAULT 0, reserved_minor bigint NOT NULL DEFAULT 0, fetched_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (creator_id, provider, currency));
CREATE TABLE IF NOT EXISTS public.payment_payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL, provider_transfer_id text UNIQUE, amount_minor bigint NOT NULL CHECK (amount_minor > 0), currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), status text NOT NULL DEFAULT 'requested' CHECK (length(status) <= 60), destination jsonb, failure_reason text CHECK (failure_reason IS NULL OR length(failure_reason) <= 300), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS payment_webhook_events_account_idx ON public.payment_webhook_events (account_id, received_at DESC) WHERE account_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS payment_webhook_events_unfinished_idx ON public.payment_webhook_events (received_at) WHERE outcome IN ('processing', 'failed');
CREATE INDEX IF NOT EXISTS payment_audit_log_creator_idx ON public.payment_audit_log (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS payment_fee_records_creator_idx ON public.payment_fee_records (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS payment_payouts_creator_idx ON public.payment_payouts (creator_id, created_at DESC);
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'storelib payments: there is no orders table, orders are not linked here.'; RETURN; END IF; ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS provider_payment_id text; CREATE UNIQUE INDEX IF NOT EXISTS orders_provider_payment_id_key ON public.orders (provider_payment_id) WHERE provider_payment_id IS NOT NULL; END $do$;
ALTER TABLE public.payment_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_webhook_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_audit_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_fee_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_balances ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_payouts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.payment_accounts, public.payment_webhook_events, public.payment_audit_log, public.payment_fee_records, public.payment_balances, public.payment_payouts FROM PUBLIC, anon, authenticated;
notify pgrst, 'reload schema';
